'use strict';

// A second presentation layer. The original flow, role allocation and voice
// simulation remain shared with the first design.
const noirStageNames={entrance:'게임 시작',orientation:'입장 안내',lobby:'대기실',role:'비밀 역할',briefing:'발언 준비',discussion:'음성 토론',vote:'관점 추리',result:'정체 공개',reflection:'게임 회고'};
const noirRole=()=>typeof myRoleName==='function'?myRoleName():'과제가 많은 학생';
const noirPerspective=()=>rolePerspectives[noirRole()]||Object.values(rolePerspectives)[0];
const noirName=i=>i===0?userName():esc(people[i].name);
const noirPortrait=(i,cls='')=>`<span class="noir-portrait portrait-${i%6} ${cls}" role="img" aria-label="${i===0?esc(state.nickname||'유나'):esc(people[i]?.name||'참가자')} 캐릭터"></span>`;

avatar=function(id,cls='avatar'){return noirPortrait(id,cls);};
participants=function(){const speaking=voice.active?0:voice.completed?-1:1;return `<div class="participants game-players" aria-label="토론 참가자 6명">${people.map((p,i)=>`<button class="game-player ${i===speaking?'speaking':''} ${i===0?'is-me':''}" data-noir-player="${i}" aria-label="${i===0?'나':p.name} 참가자 보기"><span class="seat-number">${String(i+1).padStart(2,'0')}</span>${noirPortrait(i)}<span class="player-overlay"></span><span class="player-caption"><strong>${noirName(i)}${i===0?'<small>나</small>':''}</strong><span>${i===speaking?'<i class="tiny-audio"><i></i><i></i><i></i></i> 말하는 중':i===0&&voice.completed?'<i class="online-dot"></i> 발언 완료':'<i class="online-dot"></i> 참여 중'}</span></span>${i===speaking?'<span class="player-live">VOICE</span>':''}</button>`).join('')}</div>`;};

roleCard=function(large=false){
 if(large&&!state.roleRevealed)return `<section class="large-role dossier-unopened"><div class="dossier-emblem">${icon('mask',68)}</div><span class="eyebrow">CONFIDENTIAL</span><h2>나에게만 주어진<br>또 하나의 시선.</h2><p>준비되면 비밀 역할을 확인하세요.</p><span class="dossier-seal">FOR YOUR EYES ONLY</span></section>`;
 const p=noirPerspective();
 return `<section class="${large?'large-role':'role-mini'} game-dossier"><div class="panel-heading"><span>${icon('lock',13)} 나의 비밀 역할</span>${!large?`<button data-action="toggle-secret" aria-label="${state.secretHidden?'내 역할 보기':'내 역할 숨기기'}">${icon(state.secretHidden?'eye':'hide',14)}${state.secretHidden?'보기':'숨기기'}</button>`:'<small>PRIVATE</small>'}</div>${!large&&state.secretHidden?`<div class="secret-hidden">${icon('lock',35)}<p>역할을 숨겼어요.</p><span>보기 버튼으로 다시 확인하세요.</span></div>`:`<div class="dossier-person">${noirPortrait(0)}<span class="dossier-type">MY ROLE</span></div><div class="role-content"><span class="role-category">${typeof myAssignment==='function'&&myAssignment().switcher?'역할 전환자 · 나에게만 공개':'나에게만 공개되는 역할'}</span><h2>${esc(noirRole())}</h2><p class="role-focus">${esc(p.focus)}</p><div class="dossier-rule"></div><span class="role-task-label">지키고 싶은 것</span><p class="dossier-goal">${esc(p.goal)}</p><span class="role-task-label">걱정하는 것</span><p class="dossier-goal">${esc(p.concern)}</p></div>`}</section>`;
};

screens.entrance=()=>`<section class="noir-welcome"><div class="welcome-copy"><p class="game-kicker"><span></span> WHOSE SIDE? · BY BRIDGE</p><h1>다른 얼굴.<br>같은 테이블.</h1><p class="noir-welcome-description">역할 뒤에 숨은 관점을 찾아보세요.<br>목소리로 토론하고, 말 속의 단서로 추리하는 시간.</p><div class="button-row">${button('방 코드로 입장','join-dialog','','arrow')}${button('먼저 연습해보기','practice','secondary','play')}</div><div class="welcome-game-facts"><span>${icon('users',16)} 6–8명의 플레이어</span><span>${icon('clock',16)} 약 15분</span><span>${icon('mic',16)} 음성 토론</span></div><a class="noir-teacher-link" href="mafia/index.html#teacher">선생님 수업 공간 ${icon('arrow',14)}</a></div><div class="welcome-art" aria-hidden="true"><div class="welcome-orbit"></div><div class="poster-card poster-one">${noirPortrait(2)}<span>새로운 시선</span></div><div class="poster-card poster-two">${noirPortrait(0)}<span>비밀 역할</span></div><div class="poster-card poster-three">${noirPortrait(1)}<span>숨은 관점</span></div><span class="welcome-art-caption">EVERY VOICE HAS ANOTHER SIDE.</span></div></section><section class="game-flow"><div><b>01</b><span><strong>역할을 선택하고</strong><small>내가 맡을 관점을 알아봐요.</small></span></div><div><b>02</b><span><strong>목소리로 이야기하고</strong><small>AI 요약으로 단서를 모아요.</small></span></div><div><b>03</b><span><strong>숨은 관점을 추리해요</strong><small>서로 다른 이유를 발견해요.</small></span></div></section>`;

const noirLobbyBase=screens.lobby;
screens.lobby=()=>heading('플레이어가 모였습니다.','함께할 사람과 희망 역할을 확인하고 준비해 주세요.')+`<div class="noir-lobby-grid"><section class="lobby-game-panel"><div class="game-panel-label"><span>${icon('users',16)} 플레이어 대기석</span><small>ROOM 2046</small></div><div class="lobby-player-grid">${people.map((p,i)=>`<article class="lobby-player">${noirPortrait(i)}<span class="seat-number">${String(i+1).padStart(2,'0')}</span><div><strong>${noirName(i)} ${i===0?'<small>나</small>':''}</strong><span class="lobby-ready ${i!==0||state.ready?'yes':''}">${i!==0||state.ready?'READY':'WAITING'}</span></div></article>`).join('')}</div><div class="lobby-topic"><span class="eyebrow">TODAY’S ISSUE</span><h2>${esc(topic)}</h2></div></section><aside class="lobby-ready-panel"><span class="eyebrow">BEFORE WE BEGIN</span><h2>좋은 추리는,<br>좋은 대화에서.</h2><ul><li>${icon('lock',17)} 비밀 역할은 나만 확인해요.</li><li>${icon('mic',17)} 한 사람씩 목소리로 말해요.</li><li>${icon('eye',17)} 사람보다 발언에서 단서를 찾아요.</li></ul><div class="lobby-ready-count"><span>준비한 플레이어</span><strong>${state.ready?'6':'5'} <small>/ 6</small></strong></div>${button(state.ready?'비밀 역할 받기':'준비됐어요',state.ready?'go-role':'ready','wide',state.ready?'arrow':'check')}<button class="text-button" data-go="orientation">영상과 규칙 다시 보기 ${icon('arrow',13)}</button><p class="fine">희망 역할 두 개를 고르면 준비할 수 있어요.</p></aside></div>${preferencesPanel()}`;

const noirRoleBase=screens.role;
screens.role=()=>{if(!preferencesReady()||!state.ready)return heading('어떤 역할로 시작할까요?','내 생각과 가까운 두 역할을 선택하면 비밀 역할을 배정해요.')+preferencesPanel();return heading('당신의 비밀 역할이 도착했습니다.','다른 플레이어에게는 공개되지 않는 나만의 카드입니다.')+`<div class="large-role-wrap">${roleCard(true)}<div class="role-explanation"><span class="game-kicker">YOUR SECRET ROLE</span><h2>${state.roleRevealed?'이번엔 이 사람의<br>시선으로 이야기해요.':'이 카드 뒤에,<br>또 다른 내가 있어요.'}</h2><p class="section-description">${state.roleRevealed?esc(noirPerspective().about):'선택한 희망 순위를 바탕으로 역할이 배정돼요. 나와 다른 입장이라면 무엇을 걱정하고 바랄지 생각해 보세요.'}</p>${state.roleRevealed?button('발언 준비하기','go-briefing'):button('비밀 역할 공개','reveal-role','','eye')}<p class="privacy-line">${icon('lock',13)} 이 역할은 나에게만 보여요.</p></div></div>`;};

screens.discussion=()=>`<div class="game-hud"><div class="day-phase"><span class="day-sun">☀</span><div><strong>DAY 01 <span>자유 토론</span></strong><p>모든 목소리에는, 또 다른 시선이 있어요.</p></div></div><div class="timer-block"><span>토론 종료까지</span><div id="timer-time" class="timer-time">${timeText()}</div><button class="timer-control" data-action="timer" aria-label="${timerRunning?'타이머 일시정지':'시연 타이머 재생'}">${icon(timerRunning?'pause':'play',12)}${timerRunning?'일시정지':'시연 재생'}</button></div></div><div class="game-topic"><span>오늘의 이슈</span><h1>${esc(topic)}</h1><span class="topic-badge">관점 추리</span></div>${participants()}<div class="discussion-grid noir-discussion"><section class="voice-room"><div class="game-channel-header"><div><span class="channel-live-dot"></span><strong>공개 음성 채널</strong><small>PUBLIC FREQUENCY</small></div><span>${icon('users',13)} 6명 접속</span></div><div class="conversation-tabs"><div class="tab-buttons" role="tablist" aria-label="토론 도구">${[['voice','실시간 음성'],['transcripts','요약 기록'],['notes','비밀 메모']].map(([id,label])=>`<button role="tab" class="${voiceTab===id?'active':''}" data-voice-tab="${id}" aria-selected="${voiceTab===id}" id="${id}-tab" aria-controls="voice-body">${icon(id==='voice'?'mic':id==='transcripts'?'note':'lock',14)}${label}</button>`).join('')}</div><span class="channel-secure">${icon('lock',11)} 모둠 전용</span></div><div id="voice-body" role="tabpanel" aria-labelledby="${voiceTab}-tab"></div></section><aside class="game-side"><div id="role-mini-container">${roleCard()}</div><button class="game-event-card" data-action="event-card"><span class="game-event-icon">${icon('note',20)}</span><span><small>NEW EVIDENCE</small><strong>새로운 상황이 도착했어요</strong></span>${icon('arrow',16)}</button><div class="game-vote-next"><p>말 속에서 다른 관점을 찾았나요?</p>${button('관점 추리 시작','go-vote','wide','mask')}</div></aside></div>`;

const noirVoteBase=screens.vote;
screens.vote=()=>noirVoteBase().replace('누구의 시선이었을까요?','말 속에 숨은 관점을 찾아라.').replace('나의 추리','MY DEDUCTION');
const noirResultBase=screens.result;
screens.result=()=>`<div class="noir-reveal-banner"><span>${icon('mask',26)}</span><div><p>THE OTHER SIDE</p><h2>감춰졌던 관점이 드러납니다.</h2></div></div>`+noirResultBase();

rationale=function(){return `<div class="rationale-header"><p class="eyebrow">DESIGN 02 · GAME INTERFACE</p><h1>게임의 몰입감으로,<br>다른 시선을 만나는 토론.</h1><p>캐릭터, 비밀 역할, 음성 채널, 단서와 추리를 중심으로 다시 구성한 두 번째 인터페이스입니다.</p></div><div class="principles"><article class="principle"><span>01</span><h2>함께 있는 플레이어</h2><p>프로필을 일러스트 카드로 보여주고, 지금 말하는 사람을 음성 표시와 테두리로 구분합니다.</p></article><article class="principle"><span>02</span><h2>게임 안의 음성 토론</h2><p>채팅 입력창 대신 마이크를 중심에 두었습니다. 발언 중 핵심과 이유가 요약되고 원문도 확인할 수 있습니다.</p></article><article class="principle"><span>03</span><h2>역할에서 추리까지</h2><p>비밀 역할은 개인 패널에, 새로운 상황과 추리 버튼은 그 아래에 배치해 다음 행동이 이어지게 했습니다.</p></article></div><section class="design-notes-section"><h2>두 시안을 직접 비교하세요.</h2><div class="button-row"><a class="button secondary" href="index.html#discussion">01 기존 디자인 ${icon('arrow',15)}</a>${button('02 추리 게임 체험','go-discussion')}</div></section><section class="design-notes-section"><h2>입장 전 안내도 같은 흐름으로.</h2><p class="section-description">이슈 소개 영상 → 게임 소개 영상 → 게임 규칙 → 대기실. 두 영상은 동일한 양식을 사용하며, 실제 영상 재생 없이 진행할 수 있습니다.</p><div class="journey-map">${stages.map((s,i)=>`<button class="map-step" data-go="${s.id}"><small>${String(i+1).padStart(2,'0')}</small><b>${noirStageNames[s.id]||s.label} ${icon('arrow',13)}</b><p>${s.desc}</p></button>`).join('')}</div></section><div class="limit-note">회의용 인터랙티브 시안입니다. 음성과 AI 요약은 예시 시뮬레이션이며, 실제 학생 데이터나 다중 접속을 연결하지 않았습니다.</div><a class="source-link" href="https://www.mafia42.com/" target="_blank" rel="noopener">게임 구성 참고 · 마피아42 공식 사이트 ↗</a>`;};

const noirBaseRender=render;
const noirBaseSummary=summarizeDemo;
summarizeDemo=function(text,person=0){
 const result=noirBaseSummary(text,person),p=noirPerspective(),clean=String(text||'');
 if(person===0){
  if(clean.includes(p.goal))result.claim=p.goal;
  const firstConcern=p.concern.match(/^[^.!?]+[.!?]?/)?.[0];
  if(firstConcern&&clean.includes(firstConcern))result.reason=firstConcern;
  if(clean.includes(p.concern))result.reason=p.concern;
 }
 return result;
};
const noirBaseVoice=renderVoice;
renderVoice=function(){
 noirBaseVoice();const label=$('.voice-speaker p');if(label)label.textContent=voice.active||voice.completed?noirRole():assignedPerspective(1)+'의 입장으로 이야기해요.';
 const dock=$('#mafia-mic-dock');if(dock)dock.innerHTML=`<button class="room-hand ${handRaised?'active':''}" data-action="raise-hand" aria-pressed="${handRaised}" aria-label="${handRaised?'발언 요청 취소':'발언권 요청'}">${icon('hand',19)}</button><button class="room-mic ${voice.active?'recording':''}" data-action="voice-toggle" aria-pressed="${voice.active}">${icon(voice.active?'stop':'mic',19)}<span>${voice.active?'말하기 마치기':voice.completed?'다시 말하기':'마이크를 누르고 이야기하세요'}</span></button><button class="room-deduce" data-go="vote">추리</button>`;
};
render=function(){
 noirBaseRender();
 document.body.dataset.page=current;
 document.body.classList.toggle('teacher-mode',isTeacher());
 $('.demo-label').textContent='DESIGN 02 · 추리 게임 시안';
 $$('#journey-nav [data-go]').forEach(b=>{const id=b.dataset.go;if(noirStageNames[id])b.innerHTML=`<span class="nav-number">${icon(id==='discussion'?'mic':id==='role'?'mask':id==='vote'?'eye':id==='entrance'?'play':id==='lobby'?'users':id==='reflection'?'note':id==='result'?'star':'book',16)}</span>${noirStageNames[id]}`;});
 document.title='whose side? — '+(isTeacher()?'선생님 공간':view==='rationale'?'게임 디자인 노트':noirStageNames[current]||'추리 게임');
};

document.addEventListener('click',e=>{const player=e.target.closest('[data-noir-player]');if(!player)return;const i=Number(player.dataset.noirPlayer);openModal(`<p class="eyebrow">PLAYER ${String(i+1).padStart(2,'0')}</p><div class="profile-modal-art">${noirPortrait(i)}</div><h2 id="modal-title">${noirName(i)}${i===0?' · 나':''}</h2><p>각자의 비밀 역할은 공개되지 않아요.<br>이 사람이 어떤 시선으로 말하는지 발언에서 찾아보세요.</p>${button('음성 채널로 돌아가기','close-modal','wide')}`);});
document.addEventListener('click',e=>{if(e.target.closest('[data-noir-dossier]'))openModal(`<h2 id="modal-title">나의 비밀 역할</h2><div id="role-mini-container">${roleCard()}</div>`);});
screens.discussion=()=>`<section class="mafia-room" aria-label="음성 토론 게임방"><header class="mafia-room-bar"><button data-go="lobby" aria-label="대기실로">${icon('back',18)}</button><span class="mafia-day">☀ <b>1번째 낮</b></span><div class="mafia-clock"><button class="timer-control" data-action="timer" aria-label="${timerRunning?'타이머 일시정지':'시연 타이머 재생'}">${icon(timerRunning?'pause':'play',11)}</button><span id="timer-time">${timeText()}</span></div><button data-noir-dossier aria-label="내 비밀 역할 보기">${icon('mask',19)}</button></header><div class="mafia-topic"><span>2046번 방 · 오늘의 이슈</span><h1>${esc(topic)}</h1></div><section class="voice-room"><div class="conversation-tabs"><div class="tab-buttons" role="tablist" aria-label="토론 도구">${[['voice','음성 토론'],['transcripts','AI 요약 기록'],['notes','내 메모']].map(([id,label])=>`<button role="tab" class="${voiceTab===id?'active':''}" data-voice-tab="${id}" aria-selected="${voiceTab===id}" id="${id}-tab" aria-controls="voice-body">${label}</button>`).join('')}</div><button class="room-event" data-action="event-card" aria-label="새로운 상황 카드">${icon('note',14)}</button></div><div id="voice-body" role="tabpanel" aria-labelledby="${voiceTab}-tab"></div></section><div class="mafia-player-deck">${participants()}</div><div class="mafia-mic-dock" id="mafia-mic-dock"></div><footer class="mafia-room-footer"><button data-noir-dossier>${icon('mask',13)}내 역할</button><span>음성·AI는 예시 시연입니다.</span><button data-action="event-card">${icon('note',13)}상황 카드</button></footer></section>`;
render();
